/** True when `operation` is a real catalog pairing for `featureType` in `domain`. */
export function isReferenceOperation(
  domain: 'sheet_metal' | 'machining',
  featureType: string,
  operation: string,
): boolean {
  const table = REFERENCE_FEATURE_OPERATIONS[domain] as Record<string, readonly string[]>;
  return (table[featureType] ?? []).includes(operation);
}
